package com.ruoyi.fashion.application.pool;
import java.math.BigDecimal;
import java.util.*;
import com.ruoyi.fashion.domain.product.FashionProductImage;
public final class PoolModels {
 private PoolModels() {}
 public record GroupFilter(String label,List<String> categoryLeafCodes,List<String> seasons,List<String> genders,List<String> brands,List<String> itemNos,List<String> articleNos,List<String> mainSkuCodes,String keyword,List<String> colors,List<String> sizes,String warehouseCode,String stockStatus,Long stockMin,Long stockMax,BigDecimal groupPriceMin,BigDecimal groupPriceMax,BigDecimal vipPriceMin,BigDecimal vipPriceMax,Boolean requireAllSizes,String stockFreshness,List<String> styles,String fabricComposition,List<String> fits,List<String> scenes,Boolean hasMainImage,Boolean imagesConfirmed,List<String> sourceCodes,List<String> styleCodes,List<String> skuCodes,List<String> sizeSystems,Map<String,String> attributeFilters,Long quantity,Integer unitsPerSet,String stockAsOfFrom,String stockAsOfTo,Boolean attributesConfirmed,String material,List<String> tags,Map<String,AttributeRange> attributeRanges) {
 public GroupFilter(String label,List<String> categoryLeafCodes,List<String> seasons,List<String> genders,List<String> brands,List<String> itemNos,List<String> articleNos,List<String> mainSkuCodes,String keyword,List<String> colors,List<String> sizes,String warehouseCode,String stockStatus,Long stockMin,Long stockMax,BigDecimal groupPriceMin,BigDecimal groupPriceMax,BigDecimal vipPriceMin,BigDecimal vipPriceMax){this(label,categoryLeafCodes,seasons,genders,brands,itemNos,articleNos,mainSkuCodes,keyword,colors,sizes,warehouseCode,stockStatus,stockMin,stockMax,groupPriceMin,groupPriceMax,vipPriceMin,vipPriceMax,null,null,null,null,null,null,null,null,null,null,null,null,null,null,null,null,null,null,null,null,null);}
 }
 public record AttributeRange(String from,String to){}
 public record Create(String title,List<GroupFilter> groups,String priceBasis,BigDecimal totalMin,BigDecimal totalMax,Integer activeGroupCount,List<GroupFilter> draftGroups,GroupFilter totalConditions,List<Map<String,String>> inheritance) {
  public Create(String title,List<GroupFilter> groups,String priceBasis,BigDecimal totalMin,BigDecimal totalMax){this(title,groups,priceBasis,totalMin,totalMax,null,null,null,null);}
 }
 public record Variant(String productId,String skuCode,String colorCode,String colorName,String sizeCode,BigDecimal groupPrice,BigDecimal vipPrice,Long availableQty,String mainImageUrl,String mainImageKey,List<FashionProductImage> images,long visualVersion,String sizeSystem,String unit,String stockAsOf) { public Variant(String productId,String skuCode,String colorCode,String colorName,String sizeCode,BigDecimal groupPrice,BigDecimal vipPrice,Long availableQty,String mainImageUrl,String mainImageKey,List<FashionProductImage> images,long visualVersion){this(productId,skuCode,colorCode,colorName,sizeCode,groupPrice,vipPrice,availableQty,mainImageUrl,mainImageKey,images,visualVersion,null,null,null);} }
 public record MainSku(String key,String mainSkuCode,String name,String sourceCode,String categoryLeafCode,String brand,String itemNo,String articleNo,String productId,String mainImageUrl,BigDecimal groupPriceMin,BigDecimal groupPriceMax,BigDecimal vipPriceMin,BigDecimal vipPriceMax,Long availableQty,boolean stockUnknown,String currency,String taxMode,List<Variant> variants,String styleCode,String categoryLeafPath,Map<String,String> attributes,String stockAsOf) { public MainSku(String key,String mainSkuCode,String name,String sourceCode,String categoryLeafCode,String brand,String itemNo,String articleNo,String productId,String mainImageUrl,BigDecimal groupPriceMin,BigDecimal groupPriceMax,BigDecimal vipPriceMin,BigDecimal vipPriceMax,Long availableQty,boolean stockUnknown,String currency,String taxMode,List<Variant> variants){this(key,mainSkuCode,name,sourceCode,categoryLeafCode,brand,itemNo,articleNo,productId,mainImageUrl,groupPriceMin,groupPriceMax,vipPriceMin,vipPriceMax,availableQty,stockUnknown,currency,taxMode,variants,null,null,Map.of(),null);} }
 public record Group(String label,List<MainSku> items) {}
 public record Pool(String id,String title,Create request,List<Group> groups,long rawCount,long total,String createdAt) {}
 public record Combination(String id,List<MainSku> items,BigDecimal groupPriceMin,BigDecimal groupPriceMax,BigDecimal vipPriceMin,BigDecimal vipPriceMax,boolean stockUnknown,String currency,String taxMode,Long availableSets,Boolean meetsDemand) {
  public Combination(String id,List<MainSku> items,BigDecimal groupPriceMin,BigDecimal groupPriceMax,BigDecimal vipPriceMin,BigDecimal vipPriceMax,boolean stockUnknown,String currency,String taxMode){this(id,items,groupPriceMin,groupPriceMax,vipPriceMin,vipPriceMax,stockUnknown,currency,taxMode,null,null);}
 }
 public record Selection(String poolId,long rowVersion,boolean all,List<String> selectedIds,List<String> excludedIds,Map<String,String> names,List<String> orderedIds,Map<String,Map<String,String>> variantSelections) {
  public Selection { selectedIds=selectedIds==null?List.of():List.copyOf(selectedIds); excludedIds=excludedIds==null?List.of():List.copyOf(excludedIds); names=names==null?Map.of():Map.copyOf(names); orderedIds=orderedIds==null?List.of():List.copyOf(orderedIds); variantSelections=variantSelections==null?Map.of():Map.copyOf(variantSelections); }
 }
 public record ExportSelection(Pool pool,Selection selection,List<Combination> combinations) {}
}
